import subprocess; namespace='podinfo'; pods=subprocess.check_output(['kubectl','get','pods','-n',namespace,'-o','jsonpath={.items[*].metadata.name}'],text=True).split(); [print(f'\n===== {pod} =====\n' + (lambda logs: '\n'.join([line for line in logs.splitlines() if any(word in line.lower() for word in ['error','exception','failed','fatal'])]) or 'No common errors found.')(subprocess.run(['kubectl','logs',pod,'-n',namespace],capture_output=True,text=True).stdout)) for pod in pods]
